/**
 * Renders runtime.gen.ts from runtime.py (design.md §8.3). Shared by gen-runtime.ts and the
 * staleness test, so both produce byte-identical output.
 */

/** Line endings are normalized so the generated module is the same on every OS. */
export function renderRuntimeModule(runtimePy: string): string {
  const text = runtimePy.replace(/\r\n/g, '\n');
  return [
    '// GENERATED by `pnpm gen:runtime` from runtime.py. Do not edit; edit runtime.py instead.',
    `export const RUNTIME_PY: string = ${JSON.stringify(text)};`,
    '',
  ].join('\n');
}
